62	// Only the named hooks are installed: one that merely exists changes the observed order.
63	const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
64	  const all: Required<Pick<OrchestratorHooks, RecordedHook>> = {
65	    beforeSession: async () => void callOrder.push('beforeSession'),
66	    beforeUserInput: async (_session, msg) => {
67	      callOrder.push('beforeUserInput');
